contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        bool reverted;
        c.clearRequest(0, repayDirect_, isCallback_); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }

    receive() external payable {}
}

